// Always return valid n8n JSON only
try {
  const input = $json || {};

  const rawResponse = (
    input?.choices?.[0]?.message?.content ||
    input?.response ||
    input?.text ||
    ''
  ).toString();

  const language = (input.language || '').toString();

  let cleaned = rawResponse;

  cleaned = cleaned
    .replace(/```(?:json|javascript|js)?/gi, '')
    .replace(/```/g, '')
    .replace(/`/g, '')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .replace(/\[[^\]]*\]/g, '')
    .replace(/\([^)]*\)/g, '')
    .replace(/\r?\n/g, ' ')
    .replace(/\t/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const unwantedPhrases = [
    /Voice[-\s]?over\s*:/gi,
    /Voiceover\s*:/gi,
    /Script\s*:/gi,
    /Narration\s*:/gi,
    /Text\s*:/gi,
    /Here is/gi,
    /Here's/gi,
    /Sure,?/gi,
    /Certainly,?/gi,
    /Of course,?/gi,
    /I will/gi,
    /Let me/gi,
    /Thank you for listening/gi,
    /For more information/gi,
    /Visit us/gi
  ];

  for (const pattern of unwantedPhrases) {
    cleaned = cleaned.replace(pattern, ' ');
  }

  cleaned = cleaned
    .replace(/^[\s,."']+|[\s,."']+$/g, '')
    .replace(/^[-*•\d.)\s]+/, '')
    .replace(/\s+/g, ' ')
    .trim();

  const urduRegex = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF][^.!?۔]*[.!?۔]?/g;
  const urduMatches = cleaned.match(urduRegex);

  if (urduMatches && urduMatches.length > 0) {
    cleaned = urduMatches
      .map(m => m.trim())
      .filter(m => m.length > 2)
      .join(' ');
  }

  const importantWords = ['SRLINES', 'wCRM', 'WhatsApp', 'CRM'];

  for (const word of importantWords) {
    if (
      rawResponse.toLowerCase().includes(word.toLowerCase()) &&
      !cleaned.toLowerCase().includes(word.toLowerCase())
    ) {
      cleaned = `${word} ${cleaned}`.trim();
    }
  }

  cleaned = cleaned
    .replace(/https?:\/\//gi, '')
    .replace(/www\./gi, '')
    .replace(/\.com/gi, '')
    .replace(/\s+/g, ' ')
    .replace(/[،,]\s*[،,]/g, '،')
    .replace(/[.!?۔]\s*[.!?۔]+/g, '۔')
    .trim();

  if (cleaned && !/[.!?۔]$/.test(cleaned)) {
    cleaned += '۔';
  }

  return [
    {
      json: {
        voiceover_script: cleaned,
        word_count: cleaned ? cleaned.split(/\s+/).filter(Boolean).length : 0,
        character_count: cleaned.length,
        success: true
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        voiceover_script: '',
        word_count: 0,
        character_count: 0,
        success: false,
        error: error.message || ''
      }
    }
  ];
}

